contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address adr, uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount > 0, "amount must be positive");
        require(address(this).balance >= amount, "insufficient test contract balance");
        uint256 cBalanceBefore = address(c).balance;
        require(amount < cBalanceBefore, "amount must be strictly less than c's balance so the if branch is skipped");
        c.multiplicate{value: amount}(adr); if (__ESBMC_reverted()) return;
        uint256 cBalanceAfter = address(c).balance;
        assert(cBalanceAfter == cBalanceBefore + amount);
    }

    receive() external payable {}
}

